@pytest.mark.parametrize(
    "test_workspace",
    ["example_workspace"],
    indirect=True,
)
def test_lint_unreviewed_item_failure(workspace_repo, caplog):
    runner = click.testing.CliRunner()
    dotfile_path = utils.DOTSTOP_DEFAULT_FILENAME
    dotfile_content = dotfile_path.read_text()
    # we make the item ROOT-001 unreviewed for the lint to fail
    dotfile_path.write_text(
        dotfile_content.replace(
            '"ASN-1" [sha="1f35b944c99d44e6de0ef60ad8e28b1fe8d1998a7d8cf00b9654e6870ca0ed17"];',
            '"ASN-1";',
        )
    )

    result = runner.invoke(cli.main, ["manage", "lint", "--fail-on-error"])
    assert result.exit_code == ExitCodes.LINT_FAILURE
    expected_error_log = (
        "trudag.manage",
        logging.WARNING,
        "Unreviewed Item: ASN-1",
    )

    assert expected_error_log in caplog.record_tuples


