@pytest.mark.parametrize(
    "test_workspace",
    ["example_workspace"],
    indirect=True,
)
def test_lint_json_dump(workspace_repo, caplog):
    runner = click.testing.CliRunner()
    root_001_path = Path("ASN-1.md")
    root_001_content = root_001_path.read_text()
    # item ROOT-001 unreviewed and suspect link
    root_001_path.write_text(
        root_001_content.replace(
            "Alice knows Bob",
            "Alice does not knows Bob",
        )
    )

    result = runner.invoke(
        cli.main, ["manage", "lint", "--dump", "out.json", "--fail-on-error"]
    )
    assert result.exit_code == ExitCodes.LINT_FAILURE
    expected_error_log = (
        "trudag.manage",
        logging.WARNING,
        "Unreviewed Item: ASN-1",
    )

    assert expected_error_log in caplog.record_tuples

    expected_error_log = (
        "trudag.manage",
        logging.WARNING,
        "Suspect Link: ASN-1 -> TST-1",
    )

    assert expected_error_log in caplog.record_tuples

    json_dump = Path("out.json")
    assert json_dump.is_file()

    json_dump_contents: object = None
    with json_dump.open("r") as file:
        json_dump_contents = json.load(file)

    assert json_dump_contents == {
        "unreviewed_items": ["EXP-1", "ASN-1", "ASN-2", "TST-1", "TST-2"],
        "suspect_links": [
            {"parent": "EXP-1", "child": "ASN-1"},
            {"parent": "EXP-1", "child": "ASN-2"},
            {"parent": "ASN-1", "child": "TST-1"},
            {"parent": "ASN-1", "child": "TST-2"},
            {"parent": "ASN-1", "child": "DOC-1"},
            {"parent": "ASN-2", "child": "TST-3"},
            {"parent": "ASN-2", "child": "DOC-1"},
        ],
    }


