@pytest.mark.parametrize(
    "test_workspace",
    ["example_workspace"],
    indirect=True,
)
def test_init_dotfile_pass(workspace_repo, caplog):
    # We remove the .dotstop.dot file created by the workspace_repo fixture,
    # so we can create a new one successfully.
    utils.DOTSTOP_DEFAULT_FILENAME.unlink()

    runner = click.testing.CliRunner()
    runner.invoke(cli.main, ["init", "-n", "TSF"])

    expected_logs = []
    expected_logs.append(
        (
            "trudag.utils",
            logging.INFO,
            "Created new dot database at .dotstop.dot",
        )
    )

    # We remove the .dotstop.dot file created by the workspace_repo fixture,
    # so we can create a new one successfully.
    utils.NEEDS_DEFAULT_FILENAME.unlink()
    runner.invoke(cli.main, ["--needs", "init", "-n", "TSF"])
    expected_logs.append(
        (
            "trudag.utils",
            logging.INFO,
            "Created new dot database at .needs.dot",
        )
    )
    assert expected_logs == caplog.record_tuples

    # Check if we have the correctly named graph in the dot files.
    assert "digraph TSF " in utils.DOTSTOP_DEFAULT_FILENAME.read_text()
    assert "digraph TSF " in utils.NEEDS_DEFAULT_FILENAME.read_text()

    # Ensure we can then run trudag operations on the dot files.
    result = runner.invoke(cli.main, ["score"])
    assert result.exit_code == 0


