@pytest.mark.parametrize(
    "test_workspace",
    ["example_workspace", "empty_workspace"],
    indirect=True,
)
def test_example_config_file_fail(workspace_repo, caplog):
    runner = click.testing.CliRunner()

    # First we try to pass just a non-dictionary value in configuration file which should be fail correctly.
    Path(workspace_repo.working_dir).joinpath("config.yml").write_text("- key:value\n")
    assert (
        runner.invoke(cli.main, ["-c", "config.yml", "publish", "-a"]).exit_code
        != ExitCodes.SUCCESS
    )
    assert (
        "frontends.cli.utils",
        logging.CRITICAL,
        "Failed to get any key-value mapped option from the configuration file, got: ['key:value']",
    ) in caplog.record_tuples

    # Second we try to pass just an invalid yaml in configuration file which should fail correctly.
    Path(workspace_repo.working_dir).joinpath("config.yml").write_text(
        "KEY:\n\t\tVALUE_WITH_EXTRA_TABS"
    )
    assert (
        runner.invoke(cli.main, ["-c", "config.yml", "publish", "-a"]).exit_code
        != ExitCodes.SUCCESS
    )
    assert (
        "frontends.cli.utils",
        logging.CRITICAL,
        "Failed to parse configuration yaml file: while scanning for the next token\nfound character '\\t' that cannot start any token\n  in \"<unicode string>\", line 2, column 1:\n    \t\tVALUE_WITH_EXTRA_TABS\n    ^",
    ) in caplog.record_tuples


@pytest.mark.parametrize(
    "test_workspace",
    ["example_workspace", "empty_workspace"],
    indirect=True,
)
def test_default_config_file(workspace_repo, caplog):
    # Do check the log produced by loading the default config file, we temporarily set the logger level to DEBUG
    logger = logging.getLogger("trudag")
    oldLevel = logger.getEffectiveLevel()
    logger.setLevel(logging.DEBUG)

    # We create an empty config.yml to test that we load up this default file if no explicit config file is given
    Path("config.yml").touch()
    runner = click.testing.CliRunner()
    assert runner.invoke(cli.main, ["publish", "-a"]).exit_code == ExitCodes.SUCCESS
    assert (
        "trudag",
        logging.DEBUG,
        f"Loading default configuration file (config.yml) found at: {workspace_repo.working_dir}",
    ) in caplog.record_tuples

    logger.setLevel(oldLevel)
